"""Robot painting record. All motion uses the public rcb client and camera observations."""
import sys,json,time,math,os
sys.path.insert(0,'/opt/tools')
import numpy as np
from PIL import Image
from rcb_client import Robot
ROOT='/app/output'
class Painter:
 def __init__(self):
  self.r=Robot();o=self.r.get_obs(cameras=[]);self.pos=np.array(o.meta['proprio']['now'][7:10]);self.rows=[];self.n=0
 def go(self,p,speed=.07,hold=0):
  p=np.array(p);n=max(1,int(np.ceil(np.linalg.norm(p-self.pos)/(speed*.05))))
  for t in range(1,n+1):self.rows.append([*(self.pos+(p-self.pos)*t/n),0,1,0,0])
  self.pos=p
  for _ in range(round(hold/.05)):self.rows.append([*p,0,1,0,0])
 def flush(self,cams=[]):
  while self.rows:
   a=self.rows[:180];self.rows=self.rows[180:]
   res=self.r.submit('ee_pose',a,dt=.05,video='none',cameras=cams)
   self.n+=1
   with open(ROOT+'/motion_log.jsonl','a') as f:f.write(json.dumps({'chunk':self.n,'meta':res.meta})+'\n')
   if any(x.get('ik_failures',0) for x in res.meta['plan']):print('IK WARN',res.meta['plan'],flush=True)
   if res.stopped:raise RuntimeError('Partial call')
  return res
 def dip(self,c):
  x=-.16+.03*(c%5);y=.146 if c<5 else .176
  self.go([self.pos[0],self.pos[1],.065],hold=.15)
  self.go([x,y,.065],speed=.12,hold=.15)
  self.go([x,y,.024],speed=.025,hold=.4)
  self.go([x,y,.065],speed=.04,hold=.2)
 def park(self):
  self.go([self.pos[0],self.pos[1],.07],hold=.2);self.go([-.28,0,.13],speed=.12,hold=.5);self.flush()
 def capture(self,name='current',cams=['canvas_cam']):
  o=self.r.get_obs(cameras=cams)
  for c,a in o.last.items():Image.fromarray(a).save(f'{ROOT}/{name}_{c}.png')
  return o
if __name__=='__main__' and '--practice' in sys.argv:
 p=Painter();p.dip(5)
 for i,d in enumerate([.0003,.001,.002,.004,.007,.010]):
  x=-.015-i*.035
  p.go([x,-.151,.045],speed=.1,hold=.15)
  p.go([x,-.151,.0202-d],speed=.02,hold=.35)
  p.go([x,-.216,.0202-d],speed=.025,hold=.35)
  p.go([x,-.216,.045],speed=.03,hold=.2)
  p.flush()
 p.park();p.capture('practice',['practice_cam','canvas_cam','scene_cam']);print(p.r.status())
